export class RateLimiter {
  private buckets = new Map<string, Bucket>();

  constructor(
    private maxAttempts: number,
    private windowMs: number,
    private lockoutMs: number,
    private now: () => number = () => Date.now()
  ) {}

  check(key: string): { allowed: boolean; retryAfter: number; remaining: number } {
    const t = this.now();
    this.sweep(t);
    const b = this.buckets.get(key);
    if (!b) return { allowed: true, retryAfter: 0, remaining: this.maxAttempts };
    if (b.lockedUntil > t) {
      return { allowed: false, retryAfter: Math.ceil((b.lockedUntil - t) / 1000), remaining: 0 };
    }
    if (t - b.first >= this.windowMs) {
      this.buckets.delete(key);
      return { allowed: true, retryAfter: 0, remaining: this.maxAttempts };
    }
    return { allowed: true, retryAfter: 0, remaining: Math.max(0, this.maxAttempts - b.count) };
  }

  recordFailure(key: string): { locked: boolean; retryAfter: number } {
    const t = this.now();
    let b = this.buckets.get(key);
    if (!b || t - b.first >= this.windowMs) {
      b = { count: 0, first: t, lockedUntil: 0 };
      this.buckets.set(key, b);
    }
    b.count += 1;
    if (b.count >= this.maxAttempts) {
      b.lockedUntil = t + this.lockoutMs;
      return { locked: true, retryAfter: Math.ceil(this.lockoutMs / 1000) };
    }
    return { locked: false, retryAfter: 0 };
  }

  reset(key: string): void {
    this.buckets.delete(key);
  }

  private sweep(t: number): void {
    if (this.buckets.size < 5000) return;
    for (const [k, b] of this.buckets) {
      if (b.lockedUntil <= t && t - b.first >= this.windowMs) this.buckets.delete(k);
    }
  }
}

